solutionCode:
class Motor(val name: String, var speed: Double) {
    companion object {
        val MAX_SPEED = 1.0
    }
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testMaxSpeedValue() {
        Assert.assertEquals(1.0, Motor.MAX_SPEED, 0.001)
    }

    @Test
    fun testMotorCreation() {
        val motor = Motor("Left Drive", 0.5)
        Assert.assertEquals("Left Drive", motor.name)
        Assert.assertEquals(0.5, motor.speed, 0.001)
    }

    @Test
    fun testMaxSpeedIsAccessibleWithoutInstance() {
        val speed = Motor.MAX_SPEED
        Assert.assertTrue(speed > 0)
    }
}
